# -*- coding: utf-8 -*-
"""Pre-compiled in-memory templates for Tencent Mahjong.
Eliminates all filesystem/fopen/cv2.imread dependencies on Android Chaquopy.
"""
import base64
import cv2
import numpy as np

_RAW_TEMPLATES = {
    "1m": "",
    "1p": "",
    "1s": "",
    "1z": "",
    "2m": "",
    "2p": "",
    "2s": "",
    "2z": "",
    "3m": "",
    "3p": "",
    "3s": "",
    "3z": "",
    "4m": "",
    "4p": "",
    "4s": "",
    "4z": "",
    "5m": "",
    "5p": "",
    "5s": "",
    "5z": "",
    "6m": "",
    "6p": "",
    "6s": "",
    "6z": "",
    "7m": "",
    "7p": "",
    "7s": "",
    "7z": "",
    "8m": "",
    "8p": "",
    "8s": "",
    "9m": "",
    "9p": "",
    "9s": "",
}

TEMPLATES_BGR = {}
TEMPLATES_GRAY = {}

def _init():
    for name, b64_str in _RAW_TEMPLATES.items():
        data = base64.b64decode(b64_str)
        buf = np.frombuffer(data, dtype=np.uint8)
        bgr = cv2.imdecode(buf, cv2.IMREAD_COLOR)
        if bgr is not None:
            TEMPLATES_BGR[name] = bgr
            TEMPLATES_GRAY[name] = cv2.cvtColor(bgr, cv2.COLOR_BGR2GRAY)

_init()
